-- Full Spectrum grants: batch 4 (funder pages read 2026-11-01).
-- 8 new corporate / community funders. Idempotent; safe to re-run.
-- Apply: supabase db query --linked -f supabase/fs-grants-batch4.sql
begin;
select count(*) as before_total from fs_grant_deadlines;

insert into fs_grant_deadlines (funder, program, kind, deadline_date, opens_date, amount, verified, url, notes, verified_on, level, project, priority, eligibility, match_required, status, gates, next_step, next_step_due)
select * from (values
('Busey Bank','Charitable Contributions','rolling',null::date,null::date,'not published',true,'https://www.busey.com/about-us/charitable-contributions-guidelines','Online Charitable Request System (mailing addresses per region also listed). Priorities: youth, community development, health and wellness, education, diversity and the arts, in Busey markets; Cook County is listed. Requires 501(c)(3). No fixed deadline or award size published. Ask for DJ instruction, headphones or paid neighborhood artists. Not for social clubs, religious orgs, political causes or individuals.','2026-11-01'::date,'corporate','djclass',1,'501(c)(3) serving a Busey market (Cook County listed)',null,'to_research','{g0}'::text[],'Draft the online request for the DJ Lab (free youth instruction) and submit once the AG filing is in',null::date),
('Chicago Bears','Community Investments (monetary donation)','rolling',null,null,'not published',true,'https://www.chicagobears.com/forms/community-investments','Online form, submit at least 8 WEEKS before the activity: for the DJ Lab opening Jan 12 2027 that is Nov 17 2026. Pillars: education, health and wellness, military, social justice, youth and high school football. Chicago-area nonprofit; W-9 and IRS determination letter needed. One monetary donation per org per calendar year; cannot fund every request. Questions: CommunityRelations@Bears.NFL.net.','2026-11-01'::date,'corporate','djclass',1,'Chicago-area 501(c)(3); W-9 and IRS letter; one cash gift per calendar year',null,'to_research','{g0}'::text[],'Submit the community investment request before Nov 17 2026 (8 weeks ahead of the Jan 12 2027 DJ Lab opening); have W-9 and IRS letter ready','2026-11-17'::date),
('Old National Bank','Community Sponsorships','expected',null,null,'not published',true,'https://www.oldnational.com/about-us/community/sponsorships-and-grants/sponsorships/','Sponsorships (event support, usually for publicity) and separate Foundation grants (501(c)(3), IL among states, priority to low-to-moderate-income communities; see the 2026 Foundation guidelines PDF for cycle dates). Sponsorship: about 60 days notice; next-year planning in Q3 and Q4, so now. Generally excludes very small participant counts and logo-only sponsorships: pitch a community-wide Rainbow Wednesday with employee volunteering, not the 12-station class alone. Download the Foundation guidelines PDF for dates.','2026-11-01'::date,'corporate','wednesdays',2,'501(c)(3); broad community participation; low-to-moderate-income focus for Foundation grants',null,'to_research','{g0}'::text[],'Read the Foundation guidelines PDF for cycle dates and draft a 2027 Rainbow Wednesday sponsorship pitch',null),
('Trader Joe''s','Product Donations (food and beverage)','rolling',null,null,'in-kind food only',true,'https://www.traderjoes.com/home/contact-us/product-donations','Written request on letterhead delivered to the neighborhood store Donation Coordinator at least 3 WEEKS ahead. Food and beverage only; one donation per org per year company-wide, so save it for the best event. Valid tax ID required.','2026-11-01'::date,'corporate','wednesdays',3,'501(c)(3) with tax ID; one donation per org per year',null,'to_research','{}'::text[],'Pick the single event (for example the Jan 12 2027 DJ Lab opening or a Rainbow Wednesday), then hand-deliver a letterhead request 3+ weeks ahead',null),
('Raising Cane''s','Community Partnerships','rolling',null,null,'not published',false,'https://www.raisingcanes.com/community-partnerships/','Fundraisers, sponsorships, gift/goods donations. Focus areas include education and feeding the hungry. Start through the Get Started portal; the page lists no eligibility, amounts or deadlines, so ask the local restaurant what they can do (meals for student performers, teaching artists, volunteers).','2026-11-01'::date,'corporate','wednesdays',3,'Not stated on the page',null,'to_research','{}'::text[],'Open the Get Started portal and send a meals-for-youth-showcase request',null),
('Portillo''s','Community Fundraisers','rolling',null,null,'20% of in-restaurant sales on the night',true,'https://www.portillos.com/community/','Host an event at a local Portillo''s Monday through Thursday; they donate 20% of in-restaurant sales. Open to 501(c)(3) charities, schools, clubs, teams. Flyers and FAQ provided. Earned proceeds only, depends on supporters showing up; not an upfront grant. Confirm the nearest restaurant and what counts as qualifying sales.','2026-11-01'::date,'corporate','djclass',3,'501(c)(3), school, club or team',null,'to_research','{}'::text[],'Pick a Mon-Thu night and book it with the nearest restaurant; promote to families and supporters',null),
('John Walt Foundation','Young Artist Scholarship','paused',null,null,'$1,000 x 5 scholarships',true,'https://www.johnwaltfoundation.org/young-artist-scholarship','2026 applications closed; next opening not announced. Individual Chicago-area youth apply with an original piece (song etc.) via portfolio upload plus following the foundation on social media. Age range stated two ways on the page: 14-24 and 14-23. Not a Full Spectrum organizational grant: a tool to prepare older DJ Lab students for their own applications.','2026-11-01'::date,'foundation','djclass',3,'Individual youth artists, Chicago area; not organizations',null,'not_eligible','{}'::text[],'Watch for the 2027 opening; prepare eligible students'' portfolios',null),
('Alliant Credit Union Foundation','Grant Requests','paused',null,null,'not published',true,'https://www.alliantcreditunionfoundation.org/grant-requests','Grant window currently CLOSED; check back for updates. 501(c)(3) with a mission aligned to the foundation; political and religious objectives excluded; board approves. Mail: P.O. Box 661218, Chicago IL 60666-1218. Fit for technology access / digital learning is unconfirmed.','2026-11-01'::date,'foundation','djclass',3,'501(c)(3) mission-aligned; no political or religious aims',null,'to_research','{}'::text[],'Re-check the page for a reopening date before drafting',null)
) as v(funder,program,kind,deadline_date,opens_date,amount,verified,url,notes,verified_on,level,project,priority,eligibility,match_required,status,gates,next_step,next_step_due)
where not exists (select 1 from fs_grant_deadlines g where g.funder = v.funder and g.program = v.program);

select count(*) as after_total from fs_grant_deadlines;
select funder, program, kind, deadline_date, status, next_step_due from fs_grant_deadlines
where verified_on = '2026-11-01' order by funder;
commit;
